subtitle:
={{
  ((parameters) => {
    const labels = {"inputGuard":"Guard Input","outputGuard":"Guard Output","universalGuard":"Universal Firewall","analyzeText":"Analyze Text","piiRedactor":"Redact Secrets or PII","ragScanner":"Scan Document","workflowAudit":"Audit Workflow","enrollIdentity":"Enroll Identity","issuePassport":"Issue Passport","validatePassport":"Validate Passport","toolCall":"Check Tool Call","revokePassport":"Revoke Passport"};
    const options = parameters.options || {};
    const operation = parameters.operation;
    const label = labels[operation] || operation;
    let base = ["inputGuard","outputGuard","universalGuard"].includes(operation)
      ? label + " (" + String(parameters.onThreat || "BLOCK").toLowerCase() + ")"
      : label;
    const sensitivity = String(parameters.sensitivity || "BALANCED");
    if (["inputGuard","outputGuard"].includes(operation) && sensitivity !== "BALANCED") {
      base = base + " · " + sensitivity.toLowerCase();
    }
    if (["workflowAudit","enrollIdentity","issuePassport","validatePassport","revokePassport"].includes(operation)) return base;
    const engine = String(options.detectionEngine || "AUTO");
    if (engine !== "AUTO") base = base + " · " + engine.toLowerCase();
    if (operation === "piiRedactor" && options.branchOnRedaction) {
      base = base + " · branching";
    }
    return base;
  })($parameter)
}}

outputs:
={{
  ((parameters) => {
    const options = parameters.options || {};
    if (["piiRedactor"].includes(parameters.operation)) {
      if (options.branchOnRedaction) {
        return [
          { displayName: "Clean", type: "main" },
          { displayName: "Redacted", type: "main" }
        ];
      }
      return [{ displayName: "", type: "main" }];
    }
    return [
      { displayName: "Safe", type: "main" },
      { displayName: "Flagged", type: "main" }
    ];
  })($parameter)
}}
